def separate_paren_groups(paren_string: str) -> List[str]:
    # Remove spaces from the input string
    paren_string = paren_string.replace(" ", "")

    # Initialize variables
    result = []
    stack = []
    start = 0

    # Loop through the input string to identify and separate groups of nested parentheses
    for i, char in enumerate(paren_string):
        if char == '(':
            stack.append(i)
        elif char == ')':
            if not stack:
                raise ValueError("Unbalanced parentheses")
            start = stack.pop()
            if not stack:
                result.append(paren_string[start:i+1])

    # Check if groups are nested within each other
    for group in result:
        for other_group in result:
            if group != other_group and group in other_group:
                raise ValueError("Nested parentheses")

    return result
